/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var db = api.data.playbook_custom_layout;
    var contextIds = db && db.playbookContextIdsInOrder || [];
    var latestContext = "";
    if (contextIds.length > 0) {
        latestContext = contextIds[contextIds.length - 1];
    }
    return {
        playbookContextId: latestContext,
        stageContextId: event.payload.value[0]
    };
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    var db = api.data.playbook_custom_layout;
    var contextIds = db && db.playbookContextIdsInOrder || [];
    var latestContext = "";
    if (contextIds.length > 0) {
        latestContext = contextIds[contextIds.length - 1];
    }
    return {
        params: {
            selectedStage: event.payload.value[0],
            selectedPlaybook: latestContext
        }
    };
}

