script.inlineScript:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	var playbookData = api.data.playbook_custom_layout; 
	var contextId = playbookData && playbookData.selectedItem.playbookContextId; 
	var stageId = playbookData && playbookData.selectedItem.stageContextId;
	return {
		playbookContextId: contextId,
		stageContextId: stageId
	};
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		params: {
			selectedActivity: event.payload.activityContextId,
			selectedPlaybook: event.payload.playbookContextId,
			selectedStage: event.payload.stageContextId
		}
	};
}

/**
  * @param {params} params
  * @param {api} params.api
  * @param {TransformApiHelpers} params.helpers
  */
function evaluateProperty({api, helpers}) {
  if (!api.data.playbook_custom_layout.compactMode) return "both";
  return (api.data.playbook_custom_layout.selectedItem || {}).stageContextId ? "right" : "left";
}

/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    const {
        email,
        user_name
    } = event.payload.item;

    return {
        propName: "selectedUser",
        value: {
            "value": event.payload.value,
            "displayValue": event.payload.item.label,
            "email": email,
            "user_name": user_name
        }
    };
}

/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		table: api.state.experienceReordTable,
		recordId: api.state.experienceReordId,
		templateFields: `assigned_to=${api.state.selectedUser.value}`,
		useSetDisplayValue: null
	};
}
